import { Component, OnInit } from '@angular/core';

interface SubjectEvaluation {
  name: string;
  grade: 'خیلی خوب' | 'خوب' | 'قابل قبول' | 'نیاز به تلاش بیشتر';
  description: string;
}

@Component({
  selector: 'app-grade-calculator',
  templateUrl: './grade-calculator.component.html',
  styleUrls: ['./grade-calculator.component.scss']
})
export class GradeCalculatorComponent implements OnInit {

  studentName = 'علی محمدی';
  reportPeriod = 'نوبت اول (دی ماه)';

  subjects: SubjectEvaluation[] = [
    { name: 'فارسی (مهارت‌های خوانداری)', grade: 'خیلی خوب', description: 'تلفظ روان و صحیح نشانه‌ها' },
    { name: 'فارسی (مهارت‌های نوشتاری و املا)', grade: 'خیلی خوب', description: 'دقت در رسم خط و نشانه‌های هم‌صدا' },
    { name: 'ریاضی (مفاهیم و دست‌ورزی)', grade: 'خوب', description: 'توانایی جمع و تفریق تا ۱۰' },
    { name: 'علوم تجربی (مشاهده و کاوشگری)', grade: 'خیلی خوب', description: 'کنجکاوی در آزمایش‌های کلاسی' },
    { name: 'قرآن کریم (انس با کلام خدا)', grade: 'خیلی خوب', description: 'روخوانی سوره‌های کوچک کتاب' },
    { name: 'هنر و کاردستی', grade: 'خیلی خوب', description: 'خلاقیت در نقاشی و برش کاغذ' },
    { name: 'تربیت بدنی و سلامت', grade: 'خیلی خوب', description: 'مشارکت فعال در بازی‌های حرکتی' },
    { name: 'شایستگی‌های عمومی و اخلاقی', grade: 'خیلی خوب', description: 'رعایت نظم و همکاری با همکلاسی‌ها' }
  ];

  gradeOptions: Array<'خیلی خوب' | 'خوب' | 'قابل قبول' | 'نیاز به تلاش بیشتر'> = [
    'خیلی خوب', 'خوب', 'قابل قبول', 'نیاز به تلاش بیشتر'
  ];

  ngOnInit(): void {}

  get overallEvaluation(): string {
    const counts = { 'خیلی خوب': 0, 'خوب': 0, 'قابل قبول': 0, 'نیاز به تلاش بیشتر': 0 };
    this.subjects.forEach(s => counts[s.grade]++);

    if (counts['نیاز به تلاش بیشتر'] > 2) {
      return 'نیازمند همراهی و تلاش بیشتر والدین و معلم';
    } else if (counts['قابل قبول'] > 3) {
      return 'قابل قبول (متوسط رو به رشد)';
    } else if (counts['خوب'] > counts['خیلی خوب']) {
      return 'خوب و رضایت‌بخش';
    } else {
      return 'بسیار عالی و سرآمد (خیلی خوب)';
    }
  }

  printReport(): void {
    window.print();
  }
}
